int main() {
    std::string wordToFind;
    std::cout << "Enter the word to find: ";
    std::cin >> wordToFind;

    std::string line;
    int count = 0; // счетчик вхождений слова

    std::ifstream file("input.txt");
    if (!file.is_open()) {
        std::cerr << "Unable to open input file!" << std::endl;
        return 1;
    }

    while (getline(file, line)) {
        // если найдено слово, увеличить счетчик вхождений на 1
        if (line.find(wordToFind) != std::string::npos) {
            count++;
        }
    }

    std::cout << "Word '" << wordToFind << "' appears " << count << " times in input file." << std::endl;

    file.close();

    return 0;
}
